"""Generate a standalone, offline preview with example states; no server needed."""
import json,base64
from validate import ROOT,validate
errors=validate()
if errors:raise SystemExit('\n'.join(errors))
templates=[json.loads(p.read_text()) for p in sorted((ROOT/'catalog/kaleidoscope/CC0-1.0/devices').glob('*.json'))]
connectors=json.loads((ROOT/'catalog/kaleidoscope/CC0-1.0/connectors.json').read_text());paths=set(connectors.values())
for t in templates:paths.update(f['artwork'] for f in t['faces'].values())
art={p:'data:image/svg+xml;base64,'+base64.b64encode((ROOT/p).read_bytes()).decode() for p in paths}
html='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Kaleidoscope hardware library</title><style>
*{box-sizing:border-box}body{margin:0;background:#edf3f6;color:#172a40;font:15px system-ui}header{padding:24px 40px;background:#11233b;color:white}header small{color:#a2c4ce}main{max-width:1300px;margin:32px auto;padding:0 24px}h1{margin:5px 0;font-size:27px}button,select{font:inherit;padding:10px 16px;border:1px solid #ccd8e0;border-radius:7px;background:white;color:#172a40;cursor:pointer}button.active{background:#057e70;color:white}.toolbar{display:flex;gap:12px;align-items:center;flex-wrap:wrap;margin-bottom:24px}.card{background:white;padding:25px;border:1px solid #dce4eb;border-radius:12px;margin-bottom:20px}.stage{min-height:180px;display:flex;justify-content:center;align-items:center;background:#f4f7fa;padding:30px;border-radius:8px}svg{width:100%;max-height:550px}g[role=button]{cursor:pointer;outline:none}g[role=button]:focus .hit,g[aria-pressed=true] .hit{stroke:#00a48f;stroke-width:4}#info{display:grid;grid-template-columns:repeat(3,1fr);gap:15px}small,.muted{color:#60758b}.pill{padding:4px 10px;border-radius:15px;background:#eaf1f4}footer{color:#60758b;padding:20px 0;font-size:13px}@media(max-width:650px){#info{grid-template-columns:1fr}.stage{padding:5px}header{padding:20px}}
</style><header><small>KALEIDOSCOPE / COMMUNITY HARDWARE LIBRARY</small><h1>Every connection, in view.</h1><p>Original SVG faceplates · stable port IDs · reusable connector components</p></header><main><div class="toolbar"><select id="device" aria-label="Device template"></select><button id="front">Front</button><button id="rear">Rear</button><span class="pill">Illustrative generic templates</span></div><section class="card"><h2 id="name"></h2><p id="dimensions" class="muted"></p><div id="stage" class="stage"></div></section><section class="card"><h2>Port inspector</h2><div id="info">Select a connector to inspect its definition.</div><p><label>Example status <select id="state"><option value="unknown">Unknown</option><option value="healthy">Healthy</option><option value="inactive">Inactive</option><option value="warning">Warning</option><option value="fault">Fault</option></select></label></p><small>Simulated states only. Unknown is the default. Artwork contains no embedded health claims.</small></section><footer>CC0-1.0 catalog and original SVG artwork · Apache-2.0 preview code. Generic dimensions are illustrative. Exact manufacturer layouts require verification.</footer></main><script>
const DATA=__DATA__, ART=__ART__, CONNECTORS=__CONNECTORS__;
const $=id=>document.getElementById(id),NS='http://www.w3.org/2000/svg';let face='rear',selected=null,states={};
const colors={unknown:'#90a2b6',healthy:'#13a778',inactive:'#8793a3',warning:'#d48b00',fault:'#db3c4c'};
function el(tag,attrs){let e=document.createElementNS(NS,tag);for(const[k,v]of Object.entries(attrs))e.setAttribute(k,v);return e}
DATA.forEach((t,i)=>{let o=document.createElement('option');o.value=i;o.textContent=t.name;$('device').append(o)});$('device').value=DATA.findIndex(t=>t.id==='generic-server-2u');
function inspect(p){selected=p.id;let t=DATA[$('device').value];$('info').replaceChildren();for(const [label,value]of [['Port',p.label],['Connector',p.connector],['Role / face',p.role+' / '+p.face]]){let d=document.createElement('div'),s=document.createElement('small'),b=document.createElement('p');s.textContent=label;b.textContent=value;d.append(s,b);$('info').append(d)}$('state').value=states[t.id+'/'+p.id]||'unknown';render()}
function render(){let t=DATA[$('device').value],f=t.faces[face];$('name').textContent=t.name+' · '+face;$('dimensions').textContent=`${t.dimensions.heightU}U · ${t.dimensions.widthMm} mm wide · ${t.dimensions.depthMm} mm deep · ${t.accuracy}`;['front','rear'].forEach(k=>$(k).classList.toggle('active',face===k));let svg=el('svg',{viewBox:f.viewBox.join(' '),'aria-label':t.name+' '+face});svg.append(el('image',{href:ART[f.artwork],width:f.viewBox[2],height:f.viewBox[3]}));for(const p of t.ports.filter(p=>p.face===face)){let b=p.bounds,g=el('g',{role:'button',tabindex:0,'aria-label':p.label+' '+p.connector,'aria-pressed':selected===p.id});g.append(el('image',{href:ART[CONNECTORS[p.connector]],...b}));let status=states[t.id+'/'+p.id]||'unknown';g.append(el('circle',{cx:b.x+b.width-5,cy:b.y+5,r:5,fill:status==='unknown'?'white':colors[status],stroke:colors[status],'stroke-width':2}));g.append(el('rect',{...b,fill:'transparent',stroke:'transparent','stroke-width':3,class:'hit'}));let title=el('title',{});title.textContent=p.label+' · '+status;g.append(title);g.onclick=()=>inspect(p);g.onkeydown=e=>{if(['Enter',' '].includes(e.key)){e.preventDefault();inspect(p)}};svg.append(g)}$('stage').replaceChildren(svg)}
function reset(){selected=null;$('info').textContent='Select a connector to inspect its definition.';$('state').value='unknown';render()}
$('device').onchange=reset;['front','rear'].forEach(k=>$(k).onclick=()=>{face=k;reset()});$('state').onchange=()=>{if(selected){states[DATA[$('device').value].id+'/'+selected]=$('state').value;render()}};render();
</script></html>'''
html=html.replace('__DATA__',json.dumps(templates).replace('<','\\u003c')).replace('__ART__',json.dumps(art)).replace('__CONNECTORS__',json.dumps(connectors))
(ROOT/'dist').mkdir(exist_ok=True);(ROOT/'dist/preview.html').write_text(html);print(ROOT/'dist/preview.html')
